    const val CLIENT_CONVOY_ROUTE: String = "convoy.route"
    const val CLIENT_CONVOY_LEAD: String = "convoy.lead"
    const val CLIENT_CONVOY_REMOVE: String = "convoy.remove"
    const val CLIENT_CONVOY_OPEN: String = "convoy.open"
    const val CLIENT_CRUISE_OPEN: String = "cruise.open"
    const val CLIENT_CRUISE_INVITE: String = "cruise.invite"
